/**
 * The three example apps the front page shows, each with the prompt that describes it.
 *
 * Each is a real page of this site a visitor can open and use (`/demo/*`). They were written by
 * hand for the front page, not generated by a nap session, so the page calls them examples and
 * never says how many turns they took. The thumbnails under `public/landing/examples/` are
 * screenshots of those pages taken at 1280×800 and saved at 960×600; retake them when a
 * demo's look changes.
 *
 * The booking prompt is also the one the hero's session shows being typed, so it lives here once.
 */

export type ExampleApp = {
  id: "booking" | "ledger" | "launch";
  category: string;
  prompt: string;
  /** The live example, served by this app. */
  href: `/demo/${string}`;
  thumbnail: `/landing/examples/${string}.webp`;
};

export const BOOKING_PROMPT =
  "Build a cabin booking app for a quiet weekend in the Highlands. Let me choose a date, change the length of stay, and reserve the cabin.";

export const EXAMPLE_APPS: readonly ExampleApp[] = [
  {
    id: "booking",
    category: "Booking",
    prompt: BOOKING_PROMPT,
    href: "/demo/booking",
    thumbnail: "/landing/examples/booking.webp",
  },
  {
    id: "ledger",
    category: "Finance",
    prompt:
      "Build a personal finance dashboard with spending trends, recent transactions, and a clear view of my balance.",
    href: "/demo/ledger",
    thumbnail: "/landing/examples/ledger.webp",
  },
  {
    id: "launch",
    category: "Productivity",
    prompt:
      "Build a launch tracker for a small team. Show task owners and the launch date, and let me mark tasks complete.",
    href: "/demo/launch",
    thumbnail: "/landing/examples/launch.webp",
  },
];
